int n = 8;
int depth = 0;
while (n > 1) {
    n = n / 2;
    depth++;
}
System.out.println(depth);

int[] a = {5, 1, 4, 2};
int pivot = a[3];
int less = 0;
for (int i = 0; i < 3; i++) {
    if (a[i] < pivot) { less++; }
}
System.out.println(less);

int[] left = {2, 6};
int[] right = {1, 4};
int[] out = new int[4];
int i = 0, j = 0;
if (left[0] < right[0]) { out[0] = left[0]; i = 1; }
else { out[0] = right[0]; j = 1; }
System.out.println(out[0] + " " + i + " " + j);

int[] a = {4, 7, 3, 8, 6};
int pivot = a[4];
int store = 0;
int swaps = 0;
for (int i = 0; i < 4; i++) {
    if (a[i] < pivot) {
        int t = a[store]; a[store] = a[i]; a[i] = t;
        store++; swaps++;
    }
}
System.out.println(swaps + " " + store);
